from __future__ import annotations


def merge_profile(record, profile):
    merged = dict(record)
    # A null request value is just as unresolved as an omitted value.  Do not
    # let it mask a usable profile value.
    profile = profile or {}
    if merged.get("timezone") is None:
        merged["timezone"] = profile.get("timezone")
    if merged.get("currency") is None:
        merged["currency"] = profile.get("currency")
    return merged

