import json
import math
from pathlib import Path

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import REQUIRED_FIELDS


def validate_record(record):
    if not isinstance(record, dict):
        return list(REQUIRED_FIELDS)
    missing = [
        field_name
        for field_name in REQUIRED_FIELDS
        if field_name not in record or record[field_name] is None or record[field_name] == ""
    ]
    return missing


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        # A missing profile is an expected enrichment miss, not a transaction
        # failure.  The fallback policy supplies the unresolved fields.
        profile = {}
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def _validation_errors(record):
    """Collect local errors without crossing either external API boundary."""
    if not isinstance(record, dict):
        return [{"field": "record", "reason": "must be an object", "value": record}]

    errors = []
    for field_name in validate_record(record):
        errors.append({
            "field": field_name,
            "reason": "required field is missing or empty",
            "value": record.get(field_name),
        })

    if "user_id" not in validate_record(record) and not isinstance(record["user_id"], str):
        errors.append({
            "field": "user_id",
            "reason": "must be a string",
            "value": record["user_id"],
        })

    if "amount" not in validate_record(record) and (
        isinstance(record["amount"], bool)
        or not isinstance(record["amount"], (int, float))
        or not math.isfinite(record["amount"])
    ):
        errors.append({
            "field": "amount",
            "reason": "must be a finite number",
            "value": record["amount"],
        })
    return errors


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    if not isinstance(payload, list):
        raise ValueError("transaction input must be a list of records")
    results = []
    errors = []
    for index, record in enumerate(payload):
        record_errors = _validation_errors(record)
        if record_errors:
            errors.append({"index": index, "record": record, "errors": record_errors})
            continue
        enriched = enrich(record)
        normalized = normalize(enriched)
        results.append(send_transaction(normalized))
    return {
        "results": results,
        "errors": errors,
        "profile_trace": list(PROFILE_TRACE),
        "tx_trace": list(TX_TRACE),
    }
